// Recovery readiness helper: the ready count and the matrix rows (first five plans, as before).
// Runs on records.onDataQuerySuccess, masters.onDataQuerySuccess and Recovery readiness onPageLoad.
const all = queries.records.data || [], services = queries.masters.data || [];
const bia = p => (p.decisions || []).find(d => d.kind === 'bia');
const last = p => (p.decisions || []).filter(d => d.kind === 'exercise').slice(-1)[0];
const shown = all.slice(0, 5); // owner's decision: keep the 5-plan cap
const rows = shown.map(p => {
  const ex = last(p), items = p.items || [], n = items.filter(t => t.status === 'Verified').length;
  const target = (services.find(s => s.name === p.context) || {}).capacity || 0, b = bia(p);
  return {
    id: p.id,
    name: p.name,
    meta: (p.owner || '') + ' · Exercise ' + (p.due || ''),
    rto: target + ' / ' + (b && b.rpo != null ? b.rpo : '—'),
    steps: n + ' / ' + items.length,
    progress: items.length ? Math.round(n / items.length * 100) : 0,
    outcome: (ex && ex.outcome) || 'Not recorded',
    outcomeColor: ex && ex.outcome === 'Failed' ? 'var(--cc-error-systemStatus)' : 'var(--cc-primary-text)',
    elapsed: ex ? ex.elapsed + ' min recovery' : '',
    status: p.status
  };
});
return { readyLabel: all.filter(p => p.status === 'Ready').length + ' / ' + all.length, rows };

// Runbook & exercise helper: the selected plan's summary card fields and its activity history.
// Runs on records.onDataQuerySuccess and Runbook & exercise onPageLoad.
const e = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'}[c]));
const p = (queries.records.data || []).find(r => r.id === variables.recordId);
const history = ((p && p.history) || []).slice().reverse().map(h => ({
  lineHtml: '<b>' + e(h.event) + '</b> <span style="color:var(--cc-placeholder-text);">' + e(String(h.at || '').slice(0, 16).replace('T', ' ')) + '</span>',
  note: h.note || ''
}));
return {
  has: !!p,
  context: (p && p.context) || '',
  status: (p && p.status) || '',
  ownerDue: p ? ((p.owner || '') + ' · ' + (p.due || '')) : '',
  scopeLabel: 'SCOPE & CURRENT EVIDENCE · REVISION ' + ((p && p.revision) || '—'),
  scope: (p && p.scope) || '',
  history: history.length ? history : [{ lineHtml: '', note: 'Select a record to inspect its saved activity.' }]
};
